import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int in_depth, int in_height, int in_width,
    int kernel_size, int stride, int padding, int output_padding,
    int groups,
    int out_depth, int out_height, int out_width
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_depth * out_height * out_width;

    if (idx >= total_elements) return;

    int b = idx / (out_channels * out_depth * out_height * out_width);
    int remainder = idx % (out_channels * out_depth * out_height * out_width);
    int oc = remainder / (out_depth * out_height * out_width);
    remainder %= (out_depth * out_height * out_width);
    int d_out = remainder / (out_height * out_width);
    remainder %= (out_height * out_width);
    int h_out = remainder / out_width;
    int w_out = remainder % out_width;

    float value = 0.0f;

    int out_channels_per_group = out_channels / groups;
    int group = oc / out_channels_per_group;
    int in_channels_per_group = in_channels / groups;
    int start_ic = group * in_channels_per_group;

    for (int ic = start_ic; ic < start_ic + in_channels_per_group; ++ic) {
        for (int kd = 0; kd < kernel_size; ++kd) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int d_in = (d_out - kd + padding) / stride;
                    int h_in = (h_out - kh + padding) / stride;
                    int w_in = (w_out - kw + padding) / stride;

                    if (d_in >= 0 && d_in < in_depth && h_in >= 0 && h_in < in_height && 
                        w_in >= 0 && w_in < in_width && (d_out - kd + padding) % stride == 0 &&
                        (h_out - kh + padding) % stride == 0 && (w_out - kw + padding) % stride == 0) {

                        int input_idx = b * in_channels * in_depth * in_height * in_width +
                                      ic * in_depth * in_height * in_width +
                                      d_in * in_height * in_width +
                                      h_in * in_width +
                                      w_in;

                        int weight_idx = oc * (in_channels_per_group * kernel_size * kernel_size * kernel_size) +
                                       (ic - start_ic) * kernel_size * kernel_size * kernel_size +
                                       kd * kernel_size * kernel_size +
                                       kh * kernel_size +
                                       kw;

                        value += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }
    }

    if (bias) value += bias[oc];
    output[idx] = value;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int kernel_size, int stride, int padding, int output_padding,
    int groups
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_depth = input.size(2);
    int in_height = input.size(3);
    int in_width = input.size(4);
    int out_channels = weight.size(0);

    int out_depth = (in_depth - 1) * stride - 2 * padding + kernel_size + output_padding;
    int out_height = (in_height - 1) * stride - 2 * padding + kernel_size + output_padding;
    int out_width = (in_width - 1) * stride - 2 * padding + kernel_size + output_padding;

    auto output = torch::zeros({batch_size, out_channels, out_depth, out_height, out_width}, input.options());

    int total_elements = output.numel();
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), weight.data_ptr<float>(), 
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_depth, in_height, in_width,
        kernel_size, stride, padding, output_padding,
        groups,
        out_depth, out_height, out_width
    );

    return output;
}
"""

conv_transpose3d_cpp_source = """
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int kernel_size, int stride, int padding, int output_padding,
    int groups
);
"""

conv_transpose3d = load_inline(
    name='conv_transpose3d',
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=['conv_transpose3d_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, 
                 padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        if in_channels % groups != 0 or out_channels % groups != 0:
            raise ValueError("Channels must be divisible by groups")

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self.weight = nn.Parameter(torch.empty(
            out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size
        ))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose3d.conv_transpose3d_cuda(
            x, self.weight, self.bias if self.bias is not None else torch.Tensor(),
            self.kernel_size, self.stride, self.padding, self.output_padding, self.groups
        )
